<script setup lang="ts">
import { notify, useFeedback } from '../services/feedback';
import { onMounted, ref } from 'vue';
import { ThumbsUp, Heart, MessageCircle, Share2, ShieldCheck } from '@lucide/vue';
import { demoReports } from '../data/demo';
import { labels } from '../types';
import { api } from '../services/api';
import { API_SERVER_URL } from '../config/api';
import type { NewsItem, User } from '../types';
import ConfirmDialog from './ConfirmDialog.vue';
import NewsIncidentDetails from './NewsIncidentDetails.vue';
const props = defineProps<{ user: User | null; demo: boolean }>(); const emit = defineEmits<{ signIn: [] }>();
type Comment = { id: number; user_id: number; name: string; body: string; created_at: string };
const items = ref<NewsItem[]>([]); const comments = ref<Record<string, Comment[]>>({}); const drafts = ref<Record<string, string>>({}); const open = ref<string | null>(null); const error = ref(''); const message = ref(''); const page = ref(1); const lastPage = ref(1); const busy = ref(false); const pending = ref<{ kind: 'comment' | 'delete'; reportId: string; commentId?: number } | null>(null);
const loading = ref(true); const commentBusy = ref(false);
const commentMeta = ref<Record<string, { has_more: boolean; next_cursor: number | null }>>({});
const sharedReport = ref(new URLSearchParams(location.search).get('news'));
useFeedback([error], [message]);
async function load() {
  loading.value = true; error.value = '';
  try {
    if (props.demo) { items.value = demoReports().filter(report => ['verified', 'assigned', 'responding', 'resolved', 'closed'].includes(report.status)).map(report => ({ report, reactions: {}, comments_count: 0, my_reaction: null })); lastPage.value = 1; return; }
    const result = await api<{ data: NewsItem[]; meta: { last_page: number } }>(`/api/news?page=${page.value}${sharedReport.value ? `&report=${encodeURIComponent(sharedReport.value)}` : ''}`);
    items.value = result.data; lastPage.value = result.meta.last_page;
  } catch (e) { error.value = (e as Error).message; } finally { loading.value = false; }
}
async function loadComments(id: string, append = false) {
  commentBusy.value = true; error.value = '';
  try {
    const after = append ? commentMeta.value[id]?.next_cursor : null;
    const result = await api<{ data: Comment[]; meta: { has_more: boolean; next_cursor: number | null } }>(`/api/news/${id}/comments${after ? `?after=${after}` : ''}`);
    const rows = append ? [...(comments.value[id] || []), ...result.data] : result.data;
    comments.value[id] = [...new Map(rows.map(row => [row.id, row])).values()]; commentMeta.value[id] = result.meta;
  } finally { commentBusy.value = false; }
}
async function moreComments(id: string) { error.value = ''; try { await loadComments(id, true); notify('More comments loaded.', 'info'); } catch (e) { error.value = (e as Error).message; } }
function allNews() { sharedReport.value = null; const url = new URL(location.href); url.searchParams.delete('news'); history.replaceState(null, '', url); page.value = 1; void load(); }
onMounted(load);
async function toggleComments(id: string) { if (open.value === id) { open.value = null; return; } try { await loadComments(id); open.value = id; } catch (e) { error.value = (e as Error).message; } }
async function react(item: NewsItem, type: 'helpful' | 'support') { if (props.demo || busy.value) return; if (!props.user) { emit('signIn'); return; } if (props.user.role !== 'citizen') return; busy.value = true; error.value = ''; try { await api(`/api/news/${item.report.id}/reactions`, { method: 'POST', body: JSON.stringify({ type }) }); notify(item.my_reaction === type ? 'Reaction removed.' : 'Reaction saved.'); await load(); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
async function commit() { if (!pending.value || props.demo || busy.value) return; message.value = ''; busy.value = true; error.value = ''; try { const { kind, reportId, commentId } = pending.value; if (kind === 'comment') { await api(`/api/news/${reportId}/comments`, { method: 'POST', body: JSON.stringify({ body: drafts.value[reportId] }) }); drafts.value[reportId] = ''; } else await api(`/api/news/${reportId}/comments/${commentId}`, { method: 'DELETE' }); await loadComments(reportId); message.value = kind === 'comment' ? 'Comment posted. Use Load more comments for later pages.' : 'Comment deleted.'; await load(); pending.value = null; } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
function shareUrl(id: string) { return new URL(`${API_SERVER_URL}/news/${encodeURIComponent(id)}`, location.origin).toString(); }
async function copyLink(id: string) { message.value = ''; try { await navigator.clipboard.writeText(shareUrl(id)); message.value = 'News link copied.'; } catch (e) { error.value = (e as Error).message; } }
async function share(id: string) { message.value = ''; const url = shareUrl(id); try { if (navigator.share) { await navigator.share({ title: 'Confirmed hazard report - MuniAlert', url }); notify('News shared.'); } else { await navigator.clipboard.writeText(url); message.value = 'News link copied.'; } } catch (e) { if ((e as Error).name !== 'AbortError') error.value = (e as Error).message; } }
</script>
<template><div class="news-list" :aria-busy="loading"><button v-if="sharedReport" class="button secondary" @click="allNews">View all news</button><p class="news-intro field-help"><ShieldCheck :size="18" aria-hidden="true" />{{ demo ? 'Fictional verified reports. Interactions are disabled in preview.' : 'Incident updates and submitter credit reviewed by your municipality. Contact information, exact locations and original evidence stay private.' }}</p><p v-if="loading && !items.length" class="news-loading" role="status">Loading verified news…</p><article v-for="item in items" :key="item.report.id" class="news-card" :id="`news-${item.report.id}`"><div class="news-top"><span class="status" :class="item.report.status">{{ labels[item.report.status] }}</span><small>{{ new Date(item.report.published_at || item.report.created_at).toLocaleString('en-PH', { timeZone: 'Asia/Manila' }) }} PHT</small></div><h2>{{ item.report.title }}</h2><p>{{ item.report.description }}</p><NewsIncidentDetails :report="item.report" /><div v-if="item.report.photos.length" class="news-photos"><img v-for="photo in item.report.photos" :key="photo.id" :src="photo.url" :alt="`Verified evidence: ${item.report.title}`" loading="lazy" width="640" height="480"></div><div class="news-actions"><button :disabled="demo || busy || user?.role === 'admin'" :aria-pressed="item.my_reaction === 'helpful'" @click="react(item, 'helpful')"><ThumbsUp :size="17" aria-hidden="true" />Helpful {{ item.reactions.helpful || 0 }}</button><button :disabled="demo || busy || user?.role === 'admin'" :aria-pressed="item.my_reaction === 'support'" @click="react(item, 'support')"><Heart :size="17" aria-hidden="true" />Support {{ item.reactions.support || 0 }}</button><button :disabled="demo || commentBusy" :aria-expanded="open === item.report.id" :aria-controls="`comments-${item.report.id}`" @click="toggleComments(item.report.id)"><MessageCircle :size="17" aria-hidden="true" />Comments {{ item.comments_count }}</button><button :disabled="demo" @click="share(item.report.id)"><Share2 :size="17" aria-hidden="true" />Share</button></div><div v-if="!demo" class="social-links"><a :href="`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl(item.report.id))}`" target="_blank" rel="noopener noreferrer">Facebook</a><a :href="`https://twitter.com/intent/tweet?url=${encodeURIComponent(shareUrl(item.report.id))}`" target="_blank" rel="noopener noreferrer">X</a><a :href="`https://wa.me/?text=${encodeURIComponent(item.report.title + ' ' + shareUrl(item.report.id))}`" target="_blank" rel="noopener noreferrer">WhatsApp</a><button @click="copyLink(item.report.id)">Copy link</button></div><div v-if="open === item.report.id" class="comments" :id="`comments-${item.report.id}`" :aria-busy="commentBusy"><div v-for="comment in comments[item.report.id] || []" :key="comment.id" class="comment"><strong>{{ comment.name }}</strong><small>{{ new Date(comment.created_at).toLocaleString('en-PH', { timeZone: 'Asia/Manila' }) }} PHT</small><p>{{ comment.body }}</p><button v-if="user?.id === comment.user_id || user?.role === 'admin'" class="text-button" @click="pending = { kind: 'delete', reportId: item.report.id, commentId: comment.id }">Delete comment</button></div><button v-if="commentMeta[item.report.id]?.has_more" class="button secondary" :disabled="commentBusy" @click="moreComments(item.report.id)">{{ commentBusy ? 'Loading…' : 'Load more comments' }}</button><form v-if="user?.role === 'citizen'" class="form-body" @submit.prevent="pending = { kind: 'comment', reportId: item.report.id }"><label>Add a comment<textarea v-model="drafts[item.report.id]" minlength="2" maxlength="1000" required></textarea></label><button class="button secondary" type="submit">Post comment</button></form><button v-else-if="!user" class="text-button" @click="emit('signIn')">Sign in to comment</button></div></article><p v-if="!loading && !error && !items.length" class="empty-state">No confirmed reports have been published yet.</p><div v-if="lastPage > 1" class="pagination"><button class="button secondary" :disabled="page <= 1" @click="page--; load()">Previous</button><span>{{ page }} / {{ lastPage }}</span><button class="button secondary" :disabled="page >= lastPage" @click="page++; load()">Next</button></div></div><ConfirmDialog v-if="pending" :title="pending.kind === 'delete' ? 'Delete this comment?' : 'Post your comment?'" :message="pending.kind === 'delete' ? 'The comment will be removed from the confirmed report.' : 'Your comment and account name will be visible on this news post.'" :danger="pending.kind === 'delete'" :busy="busy" :error="error" :confirm-label="pending.kind === 'delete' ? 'Delete comment' : 'Post comment'" @close="pending = null" @confirm="commit" /></template>
